WITH "r0" AS ( SELECT "s".* FROM "public"."author" AS "s" WHERE true ORDER BY "s"."id" ASC NULLS LAST ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."name" AS "name" , coalesce( "c1"."j" , '[]') AS "articles" ) AS "%")) ORDER BY "t0"."id" ASC NULLS LAST ), '[]') FROM "r0" AS "t0" LEFT JOIN (WITH "r1" AS ( SELECT "s".* FROM "public"."article" AS "s" WHERE ( "s"."author_id" ) IN (SELECT "id" FROM "r0" ) ORDER BY "s"."published_at" DESC NULLS FIRST ) SELECT "t1"."author_id" AS "k0" , json_agg( row_to_json((SELECT "%" FROM (SELECT "t1"."title" AS "title" , "c1"."j" AS "comments" , "c2"."j" AS "author" ) AS "%")) ORDER BY "t1"."published_at" DESC NULLS FIRST ) AS "j" FROM "r1" AS "t1" LEFT JOIN LATERAL (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t2"."body" AS "body" ) AS "%")) ORDER BY "t2"."id" DESC NULLS FIRST ), '[]') AS "j" FROM ( SELECT "s".* FROM "public"."comment" AS "s" WHERE true AND "s"."article_id" = "t1"."id" ORDER BY "s"."id" DESC NULLS FIRST LIMIT 1 ) AS "t2" ) AS "c1" ON true LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t2"."name" AS "name" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND "s"."id" = "t1"."author_id" LIMIT 1 ) AS "t2" ) AS "c2" ON true GROUP BY "t1"."author_id" ) AS "c1" ON true AND "c1"."k0" = "t0"."id"
